#!/usr/bin/env bash
# Regenerate /etc/nginx/conf.d/cloudflare-realip.conf from Cloudflare's published ranges.
set -euo pipefail

DEST="${1:-/etc/nginx/conf.d/cloudflare-realip.conf}"
TMP="$(mktemp)"
trap 'rm -f "$TMP"' EXIT

{
  cat <<'HDR'
# Auto-generated by deploy/firewall/sync-cloudflare-realip.sh
# Do not edit by hand — re-run the script to refresh.

HDR

  echo "# Cloudflare IPv4 (https://www.cloudflare.com/ips-v4)"
  curl -fsSL https://www.cloudflare.com/ips-v4 | while read -r cidr; do
    [[ -n "$cidr" ]] || continue
    echo "set_real_ip_from ${cidr};"
  done
  echo
  echo "# Cloudflare IPv6 (https://www.cloudflare.com/ips-v6)"
  curl -fsSL https://www.cloudflare.com/ips-v6 | while read -r cidr; do
    [[ -n "$cidr" ]] || continue
    echo "set_real_ip_from ${cidr};"
  done
  cat <<'FOOT'

real_ip_header CF-Connecting-IP;
real_ip_recursive on;
FOOT
} >"$TMP"

install -m 644 "$TMP" "$DEST"
echo "Wrote ${DEST}"
if command -v nginx >/dev/null 2>&1; then
  nginx -t
  systemctl reload nginx
  echo "nginx reloaded"
fi
